do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-101';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: The Historical Books, Joshua to Esther$j$, $j${"questions": [{"q": "What did the LORD tell Joshua in Joshua 1:9?", "options": ["Fight alone", "Build a temple", "Be strong and of a good courage, for the LORD is with you", "Return to Egypt"]}, {"q": "What repeated pattern fills the book of Judges?", "options": ["War, treaty, trade, peace", "Teaching, exile, return, rest", "Peace, harvest, feast, rest", "Sin, oppression, a cry for help, deliverance"]}, {"q": "Which woman said, whither thou goest, I will go?", "options": ["Deborah", "Ruth", "Esther", "Hannah"]}, {"q": "Who was anointed king after God rejected Saul?", "options": ["David", "Samuel", "Jonathan", "Solomon"]}, {"q": "What happened to the northern kingdom of Israel?", "options": ["It was conquered by Assyria and scattered", "It was never attacked", "It joined Egypt", "It was taken to Persia"]}, {"q": "Which book shows God protecting the Jewish people in Persia?", "options": ["Ruth", "Nehemiah", "Esther", "Ezra"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Historical Books, Joshua to Esther$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,0,0,2}'::int[], array[$j$God told Joshua to be strong and of a good courage because the LORD was with him.$j$,$j$Israel sinned, suffered, cried out, and was delivered by a judge.$j$,$j$Ruth said these words to Naomi in Ruth 1:16.$j$,$j$Samuel anointed David, the youngest son of Jesse, in 1 Samuel 16.$j$,$j$Assyria conquered the northern kingdom and scattered its people.$j$,$j$Esther risked her life and God saved His people from Haman's plot.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Historical Books, Joshua to Esther$j$ on conflict (item_id) do nothing;
end
$seed$;
